def isDivisibleBy9(n):
    return n % 9 == 0
def isDigitSumDivisibleBy9(n):
    num_str = str(n)
    digit_sum = 0
    for c in num_str:
        digit_sum += int(c)
    return digit_sum % 9 == 0









